SELECT p.id AS position_id, s.id AS signal_id, s.generated_at, UNIX_TIMESTAMP(s.generated_at) AS epoch_s, s.signal_mode, s.decision, s.latest_price, s.atr_at_signal FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal e ON e.id = p.signal_id JOIN crypto_ai.trade_signal s ON s.symbol = p.symbol AND s.interval_code = '1m' AND s.generated_at BETWEEN DATE_SUB(e.generated_at, INTERVAL 30 MINUTE) AND e.generated_at WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, s.generated_at LIMIT 200